def sha(p): return hashlib.sha256(p.read_bytes()).hexdigest()
def source_candidate_index(texts, names):
    """Index the existing literal declaration regex, including comment text.

    Zero-width matches retain overlapping headers (for example, def theorem
    foo). Word/apostrophe names share one scan; other names keep the exact
    per-name regex. This is a text index, not a Lean parser.
    """
    shorts={name.rsplit('.',1)[-1] for name in names}
    common={short for short in shorts if re.fullmatch(r"[\w']+",short)}
    rare=shorts-common
    candidates={short:[] for short in shorts}
    headers=re.compile(
        r"(?=\b(?:theorem|lemma|def|abbrev|structure|class)\s+"
        r"((?:\w+\.)*[\w']+)(?![\w.']))")
    fallback={short:re.compile(
        r"\b(?:theorem|lemma|def|abbrev|structure|class)\s+(?:\w+\.)*"
        +re.escape(short)+r"(?![\w.'])") for short in rare}
    for module,(file,text) in texts.items():
        first={}
        for match in headers.finditer(text):
            short=match[1].rsplit('.',1)[-1]
            if short in common:
                first.setdefault(short,match.start())
        for short,pattern in fallback.items():
            match=pattern.search(text)
            if match:
                first[short]=match.start()
        newlines=[match.start() for match in re.finditer('\n',text)]
        for short,offset in first.items():
            candidates[short].append({'module':module,'file':file.replace('\\','/'),
                'line':bisect_left(newlines,offset)+1})
    return {name:candidates[name.rsplit('.',1)[-1]] for name in names}

def main():
    lock=json.loads((ROOT/'target-lock.json').read_text(encoding='utf-8'))
    source=ROOT.parent/lock['manuscript']
    coverage=json.loads((ROOT/'coverage.json').read_text(encoding='utf-8'))
    audit=json.loads((ROOT/'kernel-report.json').read_text(encoding='utf-8'))
    assert lock['target']=='ver503' and audit['target']=='ver503' and audit['result']=='PASS'
    assert coverage['target']=='ver503'
    assert sha(source)==lock['sha256']==coverage['manuscript_sha256']==audit['manuscript_sha256']
    assert sha(ROOT/'coverage.json')==audit['coverage_sha256']
    declarations={d['name']:d for d in audit['declarations']}
    registry=json.loads((ROOT/"classical-external-results.json").read_text(encoding="utf-8"))
    nodes=[dict(n) for n in OBJECTS+EXTERNAL+ROUTE]
    selected={}
    for n in nodes:
        target=n['lean_target']
        required=n['lean_targets']
        n['interface_status']='audited' if required and all(t in declarations for t in required) else 'pending'
        n['status']='external_assumed' if n['kind']=='external_result' else n['interface_status']
        n['scope']=n.get('scope','primary')
        if n['kind']=='external_result':
            n['external_reference']=next(r for r in registry['grants'] if r['id']==n['id'])
            n['audit_scope']='Only this external premise TYPE and conditional application are kernel checked. Its mathematical truth is externally assumed by human authorization, not proved by these declarations.'
        n['lean_declarations']=[t for t in required if t in declarations]
        for t in n['lean_declarations']:selected[t]=declarations[t]
        n['additional_signatures']={t:declarations[t]['type'] for t in n['lean_declarations'] if t!=target}
        n['missing_declarations']=[t for t in required if t not in declarations]
        if n['kind']!='external_result':
            n['audit_scope']='Only the explicit types of the bound declarations are certified. A conditional application never proves its producer premises or external hypotheses.'
        if target in declarations:
            n['target_signature']=declarations[target]['type'];n['signature_origin']='kernel_audit'
        elif n['lean_file'] and (ROOT/n['lean_file']).exists():
            text=(ROOT/n['lean_file']).read_text(encoding='utf-8')
            short=target.rsplit('.',1)[-1]
            match=re.search(r'(?m)^theorem '+re.escape(short)+r'\b(.*?)\s*:=\s*(?:by|\n)',text,re.S)
            if match:n['target_signature']='theorem '+short+match[1];n['signature_origin']='proposed_source_interface'
        elif n['proposed_interface']:
            n['target_signature']=n['proposed_interface'];n['signature_origin']='proposed_definition' if n['kind']=='object' else 'proposed_theorem'
    mapping={n['id']:n for n in nodes}
    assert len(mapping)==len(nodes)
    active=set();visited=set();order=[]
    def visit(label):
        assert label in mapping and label not in active,('Unknown or cyclic dependency',label)
        if label in visited:return
        active.add(label)
        for dep in mapping[label]['depends_on']:visit(dep)
        active.remove(label);visited.add(label);order.append(label)
    for label in mapping:visit(label)
    for ident in order:
        n=mapping[ident]
        n['external_dependencies']=sorted(({ident} if n['kind']=='external_result' else set()).union(*(set(mapping[d]['external_dependencies']) for d in n['depends_on'])))
        n['conditional_on_external_results']=bool(n['external_dependencies'])
        n['mathematical_prerequisites_checked']=all(mapping[d]['status']=='audited' for d in n['depends_on'])
        n['mathematical_prerequisites_available']=all(mapping[d]['status'] in {'audited','external_assumed'} for d in n['depends_on'])
        n['ready_to_formalize']=n['status']=='pending' and n['scope']=='primary' and n['mathematical_prerequisites_available'] and bool(n.get('target_signature'))
    texts={m['module']:(m['source'],(ROOT/m['source']).read_text(encoding='utf-8-sig')) for m in audit['modules']}
    source_candidates=source_candidate_index(texts,selected)
    for name,row in selected.items():
        row['source_candidates']=source_candidates[name]
    for n in nodes:
        if n['lean_target'] in selected:
            locations=selected[n['lean_target']]['source_candidates']
            if locations and not any(loc['file']==n['lean_file'] for loc in locations):
                assert len(locations)==1,(n['id'],locations)
                n['lean_file']=locations[0]['file']
            if locations:n['source_locations']=locations
    counts=dict(Counter(c['status'] for c in coverage['claims']))
    # The manuscript register is extracted dynamically; its length is not a work estimate.
    assert coverage['claims']
    certificate={'audit_sha256':sha(ROOT/'kernel-report.json'),'audit_generated_at_utc':audit['generated_at_utc'],'manuscript_sha256':lock['sha256'],'upstream_commit':audit['upstream_commit'],'upstream_lock_sha256':audit['upstream_lock_sha256'],'lean':audit['version'],'mathlib_pin':audit['mathlib_pin'],'compiled_modules':len(audit['modules']),'audited_declarations':len(audit['declarations'])}
    result={'title':'ver503: first nonrigid tight-torus pair','target':'ver503','status':'INCOMPLETE','primary_objective':coverage['primary_objective'],'certificate':certificate,'numbered_claim_counts':counts,'nodes':nodes,'topological_order':order,'lean_bindings':selected,'current_ready_frontier':[n['id'] for n in nodes if n['ready_to_formalize']],'dependency_semantics':'Precise proposed proof prerequisites, not kernel implications or grants. Source signatures remain proposed until included in the full audit.','deferred_scope':lock['deferred'],'claims':coverage['claims'],'proof_scope_clarification':'At the quadratic-filling seam, relative smoothing preserves negative Hessian determinant. Auxiliary radial diagonal signs need only hold in the explicit filler and its retained radial germ.'}
    result['classical_external_registry']=registry
    result['classical_external_registry_sha256']=sha(ROOT/'classical-external-results.json')
    result['primary_route']=[i for i in order if mapping[i]['scope']=='primary']
    result['parked_nonblocking_routes']=sorted(PARKED)
    result['construction_milestones']=[{'id':i,'title':mapping[i]['title'],'status':mapping[i]['status'],'external_dependencies':mapping[i]['external_dependencies']} for i in ORIGINAL_GATES]
    result['downstream_conditional_consumers']=[{'id':i,'title':mapping[i]['title'],'interface_status':mapping[i]['interface_status'],'scope':'Checked types retain original producer premises; no inhabitant is asserted.'} for i in DOWNSTREAM_CONSUMERS]
    result['count_semantics']='Numbered manuscript coverage, not independent problems, weighted effort or a percentage of first-pair completion.'
    OUT.mkdir(exist_ok=True)
    for name in ['blueprint.json','lean-map.json']:(OUT/name).write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    md=['# ver503: route to a nonrigid tight-torus pair','','The first objective is two noncongruent smooth embedded tight tori with exactly the same induced metric, agreement on a nonempty open set, and no open planar patch. The full Cantor-family assertion is deferred.','','The checked core retains the `TightVer401` namespace in the publication engine `lean`. The active manuscript is `../paper/paper.tex`; historical target coverage is retained separately and does not certify ver503 claims. A current local audit is required for all interface credit.','','## Construction order','','Original producer frontier: SAME selected source/core and hCore → compatible eta/rho with SAME native e → full Gin open germ → one relative smoothing on full fixed V producing final H → actual ordinary H/U/F/O family → final ordinary-family pair caller. Downstream completion, completed saddle, torus, Gauss, marking and image noncongruence have precise conditional consumers; they do not inhabit the pending original inputs.','','```mermaid','flowchart TD','  Seed[Retained SAME seed clocks field] --> Selected[Pending selected source and core hCore]','  Phase[Conditional SAME native e phase signs] --> Compatible[Pending compatible eta and rho]','  Rebase[Conditional literal ruling rebasing] --> Compatible','  Compatible --> Gin[Pending FULL open Gin germ]','  Gin --> H[Pending final H on FULL fixed V]','  Smooth[Checked relative on_sides consumer] --> H','  H --> Ordinary[Pending actual H U F O ordinary FAMILY]','  Order[Conditional source and gradient signed order] --> Ordinary','  Ordinary --> Consumer[Checked ordinary-family pair consumer]','  Selected --> Consumer','  Consumer --> Completion[Same completed scalar beta Q and FULL meridian]','  Completion --> Geometry[Checked saddle torus Gauss marking consumers]','  Geometry --> Pair[Actual pair once original premises are constructed]','```','','## Objects and exact interfaces','']
    md += ['## Authorized classical and external results','','The user authorized granting classical and published external results on 2026-10-09. The first-pair target retains `background : ClassicalExternalResults` and the additional explicit `embeddedImageReparametrization : ClassicalEmbeddedImageReparametrizationClaim` and `ellipseAxesRecognition : MarkerEllipseAxesRecognition`. The exact registry is [classical-external-results.json](../classical-external-results.json); checked interfaces are [ClassicalExternal.lean](../TightVer401/ClassicalExternal.lean). External premises are explicitly assumed, while applications and novel constructions are kernel checked. There is no asserted inhabitant of the background bundle, custom axiom, or grant of the desired torus.','']
    for grant in registry['grants']:
        md += ['- `'+grant['id']+'`: `'+grant['lean_claim']+'`. Consumers: '+', '.join(grant['consumers'])+'. '+grant['proof_note']]
        for reference in grant['sources']: md += ['  Source: ['+reference['title']+']('+reference['url']+').']
    md += ['','## Work removed from the blocking route','','General height/component topology, native intrinsic-distance instance packaging, and a general surface-area/Gauss–Bonnet development are parked alternatives. Completed helpers are retained. Neither the external premises nor retained conditional helpers discharge the actual exits, full filling/completion, saddle annulus, exact torus positive locus, affine marking or final image noncongruence.','','## Construction milestones','']
    for milestone in result['construction_milestones']: md += ['- `'+milestone['id']+'`: '+milestone['status']+' — '+milestone['title']+'.']
    md += ['', '## Downstream conditional consumers', '', 'These interface statuses come from the current local audit. An audited conditional consumer proves its stated implication and does not construct the pending source/core or universal ordinary-family inputs.', '']
    for consumer in result['downstream_conditional_consumers']: md += ['- `'+consumer['id']+'`: '+consumer['interface_status']+' — '+consumer['title']+'.']
    for n in nodes:
        md += [f"### {n['id']}: {n['title']} ({n['status']})",'',n['statement'],'','Route scope: `'+n['scope']+'`. External dependencies: '+(', '.join(n['external_dependencies']) or 'none')+'.','','Dependencies: '+(', '.join('`'+d+'`' for d in n['depends_on']) or 'none')+'.','']
        if n['proof_sketch']:md += ['Proof route: '+n['proof_sketch'],'']
        if n['lean_target']:md += ['Lean target: `'+n['lean_target']+'`; source: `'+n['lean_file']+'`.','']
        if n.get('target_signature'):md += ['Interface origin: `'+n['signature_origin']+'`.','','```lean',n['target_signature'],'```','']
        elif n['status']=='pending':md += ['The mathematical interface is specified here; a complete Lean signature still needs elaboration. This node is not counted as ready merely because its dependencies are mathematical prerequisites.','']
        for t,typ in n['additional_signatures'].items():md += ['Additional required audited interface: `'+t+'`.','','```lean',typ,'```','']
    md += ['## Current proof frontier','','Only a primary pending node with checked or explicitly externally granted prerequisites and a concrete proposed signature is listed:','']+[ '- `'+i+'`: '+mapping[i]['title'] for i in result['current_ready_frontier']]
    md += ['','## Deferred results','','Complete cylinders, linking/Han–Khuri applications, general ruled extensions, Cantor families and quotient topology are deferred. General Codazzi realization is not a prerequisite of this explicit route. Support completion remains necessary to form the torus.','','## Honest completion gates','','Full quadratic filling and downstream completed-support/saddle/torus/Gauss/marker/marked-pair consumers are checked only when their exact declarations occur in the CURRENT audit. Their ordinary producer premises remain explicit. Same-seed/inverse/margin connections preserve FINAL Y, original scalar, chosen clocks and already chosen subtype inverse. New source-bound terminal thresholds/fillings, seam embedding/matches and ONE full-carrier smoothing/Germs producers discharge only their exact statements when present in CURRENT audit. Frozen worker audits and source candidates never transfer root certification. The selected source/core gate now binds the premise-free actual seed and complete one-prefix exports and is closed only when BOTH occur in the CURRENT combined audit; final caller projection linkage remains necessary. The outstanding original gates remain coherent universal same-eta/e/rho D-family instantiation after produced Gin negative strip/compatible choice/terminal filling and rebased upper Delta, actual coherent Gin/raw jets and negative-Hessian branch-domain coverage after DERIVED literal signed height/classifier/seam/compact carrier facts, actual source topology/separation/common origin, FULL Gin open germ and nonpositive-strip domain, coherent actual Gin/raw value/gradient jets and negative-Hessian domain coverage, invocation of the actual Cartesian producer returning final H from ONE smoothing call on the FULL fixed V, populated universal OrdinaryData, and final invocation with all actual inputs. The final H gradient inverse is rebuilt from its own scalar; the raw inverse is not reused. No declaration count or historical certificate supplies these inputs.','','## Exact manuscript register','',f"The active manuscript contains {len(coverage['claims'])} numbered statements; counts are {counts}. This is a manuscript coverage register, not a first-pair completion percentage. External assumptions are not added to proved counts.",'']
    for c in coverage['claims']:
        scope='deferred from the first-pair route' if c['labels'][0] in DEFERRED else ('first pair required; Cantor clause deferred' if c['labels'][0]=='thm:main-fiber' else 'shared or torus construction')
        md += [f"- `{c['labels'][0]}`: {c['status']}; {scope}; manuscript line {c['source_line']}."]
    (OUT/'interfaces.md').write_text('\n'.join(md)+'\n',encoding='utf-8')
    (OUT/'README.md').write_text('# ver503 formalization blueprint\n\nStart with [the classical/external construction route](classical-route.md), then [the precise objects, interfaces and producer dependencies](interfaces.md). [lean-map.json](lean-map.json) binds established interfaces to the current audit. [mathematics.tex](mathematics.tex) preserves the exact manuscript statements and their scope annotations.\n\nThe human authorized classical and published external results on 2026-10-09. [The registry](../classical-external-results.json) names each accepted background statement, reference, hypotheses and consumer. Checked applications retain `ClassicalExternalResults` explicitly; these background statements are not counted as proved manuscript claims. The exact classical first-pair theorem is implemented in source and receives completion credit ONLY when its declaration occurs in the current combined kernel report.\n\nThe old ver28/ver104 arguments require [foundation translation](../research/coordination/legacy-foundation-translation-20261009.md) into the actual pinned OpenAI derivative, induced metric and Gaussian curvature definitions. Keep the same construction witnesses through consumers. General height topology, distance packaging and Gauss–Bonnet infrastructure are parked; the actual selected source/core seed and complete single prefix are audit-bound producers, while their final caller linkage, final H on full fixed V and actual universal ordinary-data family remain pending. Compatible eta/native inverse/one-rho choices are now constructed from incoming D alone; instantiate the downstream raw and smoothing chain coherently. Downstream completed-support, saddle, torus, Gauss, marking and marked-pair conditional consumers have precise audit-bound interfaces in interfaces.md; their checked implications do not supply those inputs. The final H gradient inverse must be rebuilt from that SAME H. See [the frozen same-object consumer contract](../research/coordination/ver503-consumer-contract.md) and [the source review](../research/coordination/ver503-frozen-review.md).\n\nThe full-paper and Cantor-family claims remain incomplete. See the latest dated coordinator checkpoint for the exact connected certificate and remaining producer gates.\n',encoding='utf-8')
    manuscript=source.read_text(encoding='utf-8-sig')
    annotation=r'\section*{Formalization objective and route}'+'\n'+r'The first objective is the two-realization assertion of Theorem~\ref{thm:main-fiber}. The Cantor-family clause, complete-cylinder and linking applications are deferred. Retain the checked band and bending core; use positive exits, visible connectors, differential Legendre duality, quadratic filling, a square-root neck, convex closure, the granted classical positive-Gauss tightness criterion, affine marking and a small exact sign pair. The final theorem explicitly depends on the named classical background; every paper-specific construction remains a proof obligation.'+'\n'
    annotated=manuscript.replace(r'\maketitle',r'\maketitle'+'\n'+annotation,1)
    for c in coverage['claims']:
        statement=c['statement_tex'].replace('\r\n','\n')
        note=r'\par\noindent\textbf{Formalization: '+c['status']+r'.} '+('Deferred from the first-pair objective.' if c['labels'][0] in DEFERRED else 'See the precise object and dependency interfaces in the blueprint.')+r'\par'+'\n'
        annotated=annotated.replace(statement,note+statement,1)
    assert all(annotated.count(c['statement_tex'].replace('\r\n','\n'))==1 for c in coverage['claims'])
    (OUT/'mathematics.tex').write_text(annotated,encoding='utf-8')
    def tex_escape(value):
        return ''.join({'\\':r'\textbackslash{}','_':r'\_','&':r'\&','%':r'\%','#':r'\#','{':r'\{','}':r'\}','$':r'\$'}.get(c,c) for c in value)
    overview=[r'\documentclass{article}',r'\usepackage[T1]{fontenc}',r'\usepackage[margin=1in]{geometry}',r'\usepackage{hyperref}',r'\begin{document}',r'\section*{Ver503 formalization blueprint}',r'The first target is two noncongruent isometric smooth embedded tight tori, agreeing on a nonempty open set and having no open planar patch. The whole-paper and Cantor-family assertions remain incomplete.',r'\par The exact manuscript, audited interfaces, proposed dependencies and source bindings are recorded in interfaces.md and lean-map.json. This overview accompanies the annotated mathematics.tex.',r'\section*{Object and proof interfaces}']
    for n in nodes:
        overview += [r'\subsection*{'+tex_escape(n['id']+': '+n['title'])+'}',tex_escape(n['statement']),r'\par Status: '+tex_escape(n['status'])+'.',r'\par Dependencies: '+tex_escape(', '.join(n['depends_on']) or 'none')+'.']
        if n['lean_target']:overview += [r'\par Lean target: \texttt{'+tex_escape(n['lean_target'])+'}.']
    overview += [r'\section*{Deferred scope}',r'Complete cylinders, linking applications, general ruled extensions, Cantor families and quotient topology are deferred. Support completion and tightness remain required for the torus pair.',r'\end{document}']
    (OUT/'blueprint.tex').write_text('\n'.join(overview)+'\n',encoding='utf-8')
    print(f"Ver503 blueprint rebuilt: precise construction route and {len(coverage['claims'])} manuscript coverage entries; classical torus-pair objective status bound to current kernel declarations.")

